-- Server operations use the ordinary Stage states without Planner sessions.
-- The original Planner shape remains strict; operation execution is an explicit
-- alternative selected in the immutable Stage snapshot, never inferred from IDs.
ALTER TABLE stage_executions DROP CONSTRAINT stage_execution_state_shape;
ALTER TABLE stage_executions ADD CONSTRAINT stage_execution_state_shape CHECK (
  ((state = 'preparing'::text) AND (planner_session_id IS NULL) AND (candidate_stage_result IS NULL) AND (accepted_stage_result IS NULL) AND (stage_termination IS NULL) AND (finalization_id IS NULL) AND (finalization_deadline IS NULL) AND (abort_id IS NULL) AND (abort_deadline IS NULL) AND (terminal_at IS NULL) AND NOT (stage_spec_snapshot ? 'operation'))
  OR ((state = 'running'::text) AND (planner_session_id IS NOT NULL) AND (candidate_stage_result IS NULL) AND (accepted_stage_result IS NULL) AND (stage_termination IS NULL) AND (finalization_id IS NULL) AND (finalization_deadline IS NULL) AND (abort_id IS NULL) AND (abort_deadline IS NULL) AND (planner_started_at IS NOT NULL) AND (terminal_at IS NULL) AND NOT (stage_spec_snapshot ? 'operation'))
  OR ((state = 'finalizing'::text) AND (planner_session_id IS NOT NULL) AND (candidate_stage_result IS NOT NULL) AND (accepted_stage_result IS NULL) AND (stage_termination IS NULL) AND (finalization_id IS NOT NULL) AND (btrim(finalization_id) <> ''::text) AND (finalization_deadline IS NOT NULL) AND (abort_id IS NULL) AND (abort_deadline IS NULL) AND (planner_started_at IS NOT NULL) AND (terminal_at IS NULL) AND NOT (stage_spec_snapshot ? 'operation'))
  OR ((state = 'aborting'::text) AND (candidate_stage_result IS NULL) AND (accepted_stage_result IS NULL) AND (stage_termination IS NOT NULL) AND (finalization_id IS NULL) AND (finalization_deadline IS NULL) AND (abort_id IS NOT NULL) AND (btrim(abort_id) <> ''::text) AND (abort_deadline IS NOT NULL) AND (terminal_at IS NULL) AND ((((stage_termination ->> 'phase'::text) = 'preparing'::text) AND (planner_session_id IS NULL)) OR (((stage_termination ->> 'phase'::text) = 'running'::text) AND (planner_session_id IS NOT NULL) AND (planner_started_at IS NOT NULL))) AND NOT (stage_spec_snapshot ? 'operation'))
  OR ((state = ANY (ARRAY['succeeded'::text, 'failed'::text])) AND (planner_session_id IS NOT NULL) AND (candidate_stage_result IS NOT NULL) AND (accepted_stage_result = candidate_stage_result) AND (accepted_result_schema_version = candidate_result_schema_version) AND ((accepted_stage_result ->> 'outcome'::text) = state) AND (stage_termination IS NULL) AND (finalization_id IS NOT NULL) AND (btrim(finalization_id) <> ''::text) AND (finalization_deadline IS NOT NULL) AND (abort_id IS NULL) AND (abort_deadline IS NULL) AND (planner_started_at IS NOT NULL) AND (terminal_at IS NOT NULL) AND NOT (stage_spec_snapshot ? 'operation'))
  OR ((state = ANY (ARRAY['interrupted'::text, 'cancelled'::text])) AND (candidate_stage_result IS NULL) AND (accepted_stage_result IS NULL) AND (stage_termination IS NOT NULL) AND ((stage_termination ->> 'outcome'::text) = state) AND (finalization_id IS NULL) AND (finalization_deadline IS NULL) AND (abort_id IS NOT NULL) AND (btrim(abort_id) <> ''::text) AND (abort_deadline IS NOT NULL) AND (terminal_at IS NOT NULL) AND ((((stage_termination ->> 'phase'::text) = 'preparing'::text) AND (planner_session_id IS NULL)) OR (((stage_termination ->> 'phase'::text) = 'running'::text) AND (planner_session_id IS NOT NULL) AND (planner_started_at IS NOT NULL))) AND NOT (stage_spec_snapshot ? 'operation'))
  OR (state='preparing' AND candidate_stage_result IS NULL AND accepted_stage_result IS NULL AND stage_termination IS NULL AND finalization_id IS NULL AND finalization_deadline IS NULL AND abort_id IS NULL AND abort_deadline IS NULL AND terminal_at IS NULL AND stage_spec_snapshot ? 'operation' AND jsonb_typeof(stage_spec_snapshot->'operation')='object' AND NOT (stage_spec_snapshot ? 'planner') AND planner_session_id IS NULL AND planner_invocation_id IS NULL AND planner_started_at IS NULL)
  OR (state='running' AND admitted_at IS NOT NULL AND candidate_stage_result IS NULL AND accepted_stage_result IS NULL AND stage_termination IS NULL AND finalization_id IS NULL AND finalization_deadline IS NULL AND abort_id IS NULL AND abort_deadline IS NULL AND terminal_at IS NULL AND stage_spec_snapshot ? 'operation' AND jsonb_typeof(stage_spec_snapshot->'operation')='object' AND NOT (stage_spec_snapshot ? 'planner') AND planner_session_id IS NULL AND planner_invocation_id IS NULL AND planner_started_at IS NULL)
  OR (state='finalizing' AND admitted_at IS NOT NULL AND candidate_stage_result IS NOT NULL AND accepted_stage_result IS NULL AND stage_termination IS NULL AND finalization_id IS NOT NULL AND btrim(finalization_id)<>'' AND finalization_deadline IS NOT NULL AND abort_id IS NULL AND abort_deadline IS NULL AND terminal_at IS NULL AND stage_spec_snapshot ? 'operation' AND jsonb_typeof(stage_spec_snapshot->'operation')='object' AND NOT (stage_spec_snapshot ? 'planner') AND planner_session_id IS NULL AND planner_invocation_id IS NULL AND planner_started_at IS NULL)
  OR (state IN ('succeeded','failed') AND admitted_at IS NOT NULL AND candidate_stage_result IS NOT NULL AND accepted_stage_result=candidate_stage_result AND accepted_result_schema_version=candidate_result_schema_version AND accepted_stage_result->>'outcome'=state AND stage_termination IS NULL AND finalization_id IS NOT NULL AND btrim(finalization_id)<>'' AND finalization_deadline IS NOT NULL AND abort_id IS NULL AND abort_deadline IS NULL AND terminal_at IS NOT NULL AND stage_spec_snapshot ? 'operation' AND jsonb_typeof(stage_spec_snapshot->'operation')='object' AND NOT (stage_spec_snapshot ? 'planner') AND planner_session_id IS NULL AND planner_invocation_id IS NULL AND planner_started_at IS NULL)
  OR (state='aborting' AND candidate_stage_result IS NULL AND accepted_stage_result IS NULL AND stage_termination IS NOT NULL AND finalization_id IS NULL AND finalization_deadline IS NULL AND abort_id IS NOT NULL AND btrim(abort_id)<>'' AND abort_deadline IS NOT NULL AND ((stage_termination->>'phase'='running' AND admitted_at IS NOT NULL) OR stage_termination->>'phase'='preparing') AND terminal_at IS NULL AND stage_spec_snapshot ? 'operation' AND jsonb_typeof(stage_spec_snapshot->'operation')='object' AND NOT (stage_spec_snapshot ? 'planner') AND planner_session_id IS NULL AND planner_invocation_id IS NULL AND planner_started_at IS NULL)
  OR (state IN ('interrupted','cancelled') AND candidate_stage_result IS NULL AND accepted_stage_result IS NULL AND stage_termination IS NOT NULL AND finalization_id IS NULL AND finalization_deadline IS NULL AND abort_id IS NOT NULL AND btrim(abort_id)<>'' AND abort_deadline IS NOT NULL AND ((stage_termination->>'phase'='running' AND admitted_at IS NOT NULL) OR stage_termination->>'phase'='preparing') AND terminal_at IS NOT NULL AND stage_termination->>'outcome'=state AND stage_spec_snapshot ? 'operation' AND jsonb_typeof(stage_spec_snapshot->'operation')='object' AND NOT (stage_spec_snapshot ? 'planner') AND planner_session_id IS NULL AND planner_invocation_id IS NULL AND planner_started_at IS NULL)
);
